/* Types */
export type Account = {
	/**  What a script writes: `"account": "hr.supervisor"`. */
	key: string,
	/**  What a person reads in the app. */
	label: string,
	username: string,
	password: string,
};

/**
 *  A change to the registry. Deliberately not `Debug`: it can hold a
 *  password, and nothing should be able to print one by accident.
 */
export type AccountChange = 
/**  A new account. The optional fields are left out when empty. */
{ kind: "Add"; key: string; username: string; password: string; employee_no: string; display_name: string; title: string; supervisor: string } | 
/**
 *  One field of an existing account. An empty value clears an optional
 *  field (the CLI's `-`).
 */
{ kind: "Set"; key: string; field: AccountField; value: string } | 
/**  Delete an account. The CLI refuses while anything references it. */
{ kind: "Remove"; key: string } | 
/**  Move an account to a new key, rewriting every reference (`--cascade`). */
{ kind: "Rename"; from: string; to: string };

/**  One field `set` changes. */
export type AccountField = "Username" | "Password" | "EmployeeNo" | "DisplayName" | "Title" | "Supervisor";

/**
 *  One proposed account a person picked to add. `password` is what they
 *  typed; empty means "use the password the assistant proposed with it, or
 *  else the environment's default password".
 */
export type AccountInput = {
	key: string,
	label: string,
	username: string,
	password: string,
};

/**  What uses one account, from `npm run users -- list --json`. */
export type AccountRefs = {
	key: string,
	/**  Specs that sign in as it (`test.use` or `actingAs`). */
	specs: number,
	/**
	 *  Other references: test case `**User:**` lines and supervisor
	 *  pointers. Any reference at all refuses a delete.
	 */
	other_refs: number,
};

export type Action = Action_Serialize | Action_Deserialize;

export type ActionOutcome = ActionOutcome_Serialize | ActionOutcome_Deserialize;

export type ActionOutcome_Deserialize = {
	ok: boolean,
	detail: string,
	/**
	 *  A file in the autorun `shots` folder, taken when the action failed.
	 *  A name, never a path and never the image: run files stay small, and
	 *  the webview cannot ask for anything outside that folder.
	 */
	screenshot?: string | null,
	/**
	 *  The component this action came from, when a `use_component` was
	 *  expanded into it. Left out otherwise, so older run files read the
	 *  same.
	 */
	component?: string | null,
	/**
	 *  What the page newly showed after this action changed it - toasts,
	 *  alerts, field errors (`page_messages`). Never fails the action by
	 *  itself. Left out when empty, so older run files read the same.
	 */
	page_said?: PageMessage[],
	/**
	 *  The requests this action started that the application refused
	 *  (`autorun::refusals`). Left out when empty.
	 */
	refused?: RefusedRequest_Deserialize[],
};

export type ActionOutcome_Serialize = {
	ok: boolean,
	detail: string,
	/**
	 *  A file in the autorun `shots` folder, taken when the action failed.
	 *  A name, never a path and never the image: run files stay small, and
	 *  the webview cannot ask for anything outside that folder.
	 */
	screenshot?: string | null,
	/**
	 *  The component this action came from, when a `use_component` was
	 *  expanded into it. Left out otherwise, so older run files read the
	 *  same.
	 */
	component?: string | null,
	/**
	 *  What the page newly showed after this action changed it - toasts,
	 *  alerts, field errors (`page_messages`). Never fails the action by
	 *  itself. Left out when empty, so older run files read the same.
	 */
	page_said?: PageMessage[],
	/**
	 *  The requests this action started that the application refused
	 *  (`autorun::refusals`). Left out when empty.
	 */
	refused?: RefusedRequest_Serialize[],
};

